{"cmd":"cat > evidence.json << 'JSONEOF'
{
  "event_construction": {
    "description": "Overtake events are pairwise position reversals between two drivers. Lower position numbers are better race positions.",
    "eligible_position_rows": {
      "source": "lap_positions table",
      "filter": "lap_type = 'Race'",
      "excluded": "lap_type starting with 'Retirement' (e.g., 'Retirement (Driver Error)', 'Retirement (Mechanical Problem)', 'Retirement (Disqualification)')",
      "lap_0_treatment": "lap = 0 rows are starting-position records (lap_types like 'Starting Position - Qualifying', 'Starting Position - Grid Drop', etc.) and are not used for event construction."
    },
    "lap_1_events": {
      "previous_state": "results.grid WHERE grid > 0 (from results table)",
      "current_state": "lap_positions WHERE lap = 1 AND lap_type = 'Race'",
      "grid_0_treatment": "grid = 0 treated as non-normal grid marker, excluded from previous state",
      "note": "Driver must have grid > 0 to be in previous state; must have lap 1 Race position to be in current state; must be in both to form an event."
    },
    "lap_2_and_later": {
      "previous_state": "lap_positions WHERE lap = (current_lap - 1) AND lap_type = 'Race'",
      "current_state": "lap_positions WHERE lap = current_lap AND lap_type = 'Race'"
    },
    "direction": {
      "rule": "If driver A was ahead of driver B in the previous state (lower position), and driver A is behind driver B in the current state (higher position), then driver B overtook driver A.",
      "overtaking_driver": "driver B",
